"""Highest version in a list satisfying an npm-style range. See task.md."""

from __future__ import annotations

import re
from collections import namedtuple


class RangeError(ValueError):
    """Raised for malformed range expressions and malformed versions."""


Version = namedtuple("Version", ["major", "minor", "patch", "prerelease"])

_NUM_COMPONENT = re.compile(r"0|[1-9]\d*")
_IDENTIFIER = re.compile(r"[0-9A-Za-z-]+")
_ALL_DIGITS = re.compile(r"[0-9]+")

_OPERATORS = (">=", "<=", ">", "<", "^", "~", "=")


# ---------------------------------------------------------------------------
# Identifier / version parsing helpers
# ---------------------------------------------------------------------------


def _validate_identifiers(s: str, *, numeric_no_leading_zero: bool) -> tuple:
    ids = s.split(".")
    for ident in ids:
        if not _IDENTIFIER.fullmatch(ident):
            raise RangeError(f"invalid identifier: {ident!r}")
        if numeric_no_leading_zero and _ALL_DIGITS.fullmatch(ident):
            if len(ident) > 1 and ident[0] == "0":
                raise RangeError(f"invalid numeric identifier: {ident!r}")
    return tuple(ids)


def parse_version(s: str) -> Version:
    """Parse a fully specified version string (as found in `versions`)."""
    m = re.fullmatch(
        r"(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
        r"(?:-([^+]+))?"
        r"(?:\+(.+))?",
        s,
    )
    if not m:
        raise RangeError(f"malformed version: {s!r}")
    major, minor, patch, pre, build = m.groups()
    prerelease = _validate_identifiers(pre, numeric_no_leading_zero=True) if pre is not None else ()
    if build is not None:
        _validate_identifiers(build, numeric_no_leading_zero=False)
    return Version(int(major), int(minor), int(patch), prerelease)


class _Partial:
    __slots__ = ("comps", "specified_count", "is_full", "prerelease")

    def __init__(self, comps, specified_count, is_full, prerelease):
        self.comps = comps
        self.specified_count = specified_count
        self.is_full = is_full
        self.prerelease = prerelease

    def filled(self):
        return [self.comps[i] if i < len(self.comps) and self.comps[i] is not None else 0 for i in range(3)]


def _parse_version_part(s: str) -> _Partial:
    if "+" in s:
        main, build = s.split("+", 1)
    else:
        main, build = s, None
    if "-" in main:
        core, pre = main.split("-", 1)
    else:
        core, pre = main, None

    parts = core.split(".")
    if len(parts) > 3:
        raise RangeError(f"malformed version: {s!r}")

    comps = []
    wildcard_seen = False
    for p in parts:
        if p in ("x", "X", "*"):
            wildcard_seen = True
            comps.append(None)
        else:
            if wildcard_seen:
                raise RangeError(f"malformed version: {s!r}")
            if not _NUM_COMPONENT.fullmatch(p):
                raise RangeError(f"malformed version: {s!r}")
            comps.append(int(p))

    specified_count = sum(1 for c in comps if c is not None)
    is_full = len(comps) == 3 and specified_count == 3

    if pre is not None or build is not None:
        if not is_full:
            raise RangeError(f"prerelease/build only allowed on full version: {s!r}")

    prerelease = _validate_identifiers(pre, numeric_no_leading_zero=True) if pre is not None else ()
    if build is not None:
        _validate_identifiers(build, numeric_no_leading_zero=False)

    return _Partial(comps, specified_count, is_full, prerelease)


def _increment_at(filled, idx):
    result = list(filled)
    result[idx] += 1
    for j in range(idx + 1, 3):
        result[j] = 0
    return result


# ---------------------------------------------------------------------------
# Comparator token desugaring
# ---------------------------------------------------------------------------


def _desugar_token(tok: str) -> list:
    op = None
    rest = tok
    for candidate in _OPERATORS:
        if tok.startswith(candidate):
            op = candidate
            rest = tok[len(candidate):]
            break

    if op is not None and rest == "":
        raise RangeError(f"malformed comparator: {tok!r}")

    partial = _parse_version_part(rest)

    if op is None or op == "=":
        if partial.is_full:
            return [("=", Version(*partial.filled(), partial.prerelease))]
        if partial.specified_count == 0:
            return [(">=", Version(0, 0, 0, ()))]
        filled = partial.filled()
        idx = partial.specified_count - 1
        lower = Version(*filled, ())
        upper = Version(*_increment_at(filled, idx), ())
        return [(">=", lower), ("<", upper)]

    if op in (">", ">=", "<", "<="):
        if not partial.is_full:
            raise RangeError(f"malformed comparator: {tok!r}")
        return [(op, Version(*partial.filled(), partial.prerelease))]

    if op == "^":
        if partial.specified_count == 0:
            raise RangeError(f"malformed comparator: {tok!r}")
        filled = partial.filled()
        lower = Version(*filled, partial.prerelease if partial.is_full else ())
        idx = None
        for i in range(partial.specified_count):
            if filled[i] != 0:
                idx = i
                break
        if idx is None:
            idx = partial.specified_count - 1
        upper = Version(*_increment_at(filled, idx), ())
        return [(">=", lower), ("<", upper)]

    if op == "~":
        if partial.specified_count == 0:
            raise RangeError(f"malformed comparator: {tok!r}")
        filled = partial.filled()
        lower = Version(*filled, partial.prerelease if partial.is_full else ())
        idx = 1 if partial.specified_count >= 2 else 0
        upper = Version(*_increment_at(filled, idx), ())
        return [(">=", lower), ("<", upper)]

    raise RangeError(f"malformed comparator: {tok!r}")


def _desugar_hyphen(tok_a: str, tok_b: str) -> list:
    a = _parse_version_part(tok_a)
    b = _parse_version_part(tok_b)
    if a.specified_count == 0 or b.specified_count == 0:
        raise RangeError("hyphen range requires at least a major component on both sides")

    lower = Version(*a.filled(), a.prerelease if a.is_full else ())

    if b.is_full:
        upper = ("<=", Version(*b.filled(), b.prerelease))
    else:
        b_filled = b.filled()
        idx = b.specified_count - 1
        upper = ("<", Version(*_increment_at(b_filled, idx), ()))

    return [(">=", lower), upper]


def _parse_comparator_set(text: str) -> list:
    tokens = text.split()
    if not tokens:
        raise RangeError("empty comparator set")

    if "-" in tokens:
        if len(tokens) != 3 or tokens[1] != "-":
            raise RangeError(f"malformed hyphen range: {text!r}")
        return _desugar_hyphen(tokens[0], tokens[2])

    comparators = []
    for tok in tokens:
        comparators.extend(_desugar_token(tok))
    return comparators


def parse_range(range_expr: str) -> list:
    parts = range_expr.split("||")

    if len(parts) == 1 and parts[0].strip() == "":
        return [[(">=", Version(0, 0, 0, ()))]]

    comparator_sets = []
    for part in parts:
        stripped = part.strip()
        if stripped == "":
            raise RangeError("empty side of ||")
        comparator_sets.append(_parse_comparator_set(stripped))
    return comparator_sets


# ---------------------------------------------------------------------------
# Precedence and matching
# ---------------------------------------------------------------------------


def _identifier_key(ident: str):
    if _ALL_DIGITS.fullmatch(ident):
        return (0, int(ident))
    return (1, ident)


def _precedence_key(v: Version):
    if not v.prerelease:
        pre_key = (1,)
    else:
        pre_key = (0,) + tuple(_identifier_key(i) for i in v.prerelease)
    return (v.major, v.minor, v.patch, pre_key)


def _compare(v1: Version, v2: Version) -> int:
    k1, k2 = _precedence_key(v1), _precedence_key(v2)
    return (k1 > k2) - (k1 < k2)


def _satisfies_primitive(v: Version, op: str, bound: Version) -> bool:
    cmp = _compare(v, bound)
    if op == "=":
        return cmp == 0
    if op == ">":
        return cmp > 0
    if op == ">=":
        return cmp >= 0
    if op == "<":
        return cmp < 0
    if op == "<=":
        return cmp <= 0
    raise AssertionError(op)


def _set_matches(v: Version, comparators: list) -> bool:
    if not all(_satisfies_primitive(v, op, bound) for op, bound in comparators):
        return False
    if v.prerelease:
        return any(
            bound.prerelease and (bound.major, bound.minor, bound.patch) == (v.major, v.minor, v.patch)
            for op, bound in comparators
        )
    return True


def _range_matches(v: Version, comparator_sets: list) -> bool:
    return any(_set_matches(v, cs) for cs in comparator_sets)


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


def max_satisfying(versions: list[str], range_expr: str) -> str | None:
    """Return the highest version in `versions` that satisfies `range_expr`."""
    comparator_sets = parse_range(range_expr)
    parsed = [(s, parse_version(s)) for s in versions]

    best = None
    best_key = None
    for s, v in parsed:
        if not _range_matches(v, comparator_sets):
            continue
        key = _precedence_key(v)
        if best is None or key > best_key:
            best = s
            best_key = key
    return best
